class MoveToEmptyStackRule:
    """Regla refinada: prioriza vaciar pilas, pero puede abrir una salida de emergencia."""

    name = "move_to_empty_stack_rule"

    def __init__(
        self,
        prefer_empty_only=True,
        allow_one_non_empty_escape=True,
        macro_mode=False,
        max_macro_steps=3,
    ):
        self.prefer_empty_only = bool(prefer_empty_only)
        self.allow_one_non_empty_escape = bool(allow_one_non_empty_escape)
        self.macro_mode = bool(macro_mode)
        self.max_macro_steps = int(max_macro_steps)

    @staticmethod
    def _stacks(partial):
        stacks = getattr(partial, "stacks", None)
        if stacks is not None:
            return stacks
        return []

    @classmethod
    def _height(cls, partial, idx):
        stacks = cls._stacks(partial)
        if stacks:
            return len(stacks[idx])
        if hasattr(partial, "h"):
            return partial.h(idx)
        return 0

    @classmethod
    def _top(cls, partial, idx, default=None):
        stacks = cls._stacks(partial)
        if stacks:
            return stacks[idx][-1] if stacks[idx] else default
        if hasattr(partial, "g"):
            return partial.g(idx)
        return default

    @classmethod
    def _empty_count(cls, partial):
        stacks = cls._stacks(partial)
        if stacks:
            return sum(1 for s in stacks if len(s) == 0)
        if hasattr(partial, "S"):
            return sum(1 for i in range(partial.S) if cls._height(partial, i) == 0)
        return 0

    @classmethod
    def _is_full(cls, partial, idx):
        if hasattr(partial, "H"):
            return cls._height(partial, idx) >= partial.H
        return False

    @classmethod
    def _move_attrs(cls, action):
        return getattr(action, "so", None), getattr(action, "sd", None)

    def _allowed_simple(self, partial, candidates):
        empties = [i for i in range(getattr(partial, "S", 0)) if self._height(partial, i) == 0]
        empty_count = len(empties)
        if self.prefer_empty_only and empty_count == 0:
            return []

        empty_set = set(empties)
        allowed = [a for a in candidates if self._move_attrs(a)[1] in empty_set]

        if allowed or not self.allow_one_non_empty_escape:
            return allowed

        # Escape de emergencia: si no hay destinos vacíos útiles, permite el mejor destino
        # no lleno con tope mínimo, pero solo uno por cada mejor tope.
        best_top = None
        best = []
        for a in candidates:
            so, sd = self._move_attrs(a)
            if so is None or sd is None:
                continue
            if self._is_full(partial, sd):
                continue
            top = self._top(partial, sd, default=getattr(partial, "G", 0))
            if best_top is None or top < best_top:
                best_top = top
                best = [a]
            elif top == best_top:
                best.append(a)
        return best

    def start(self, partial, memory):
        if not self.macro_mode:
            return None
        empties = self._empty_count(partial)
        return {"remaining": min(self.max_macro_steps, max(1, empties))}

    def done(self, partial, memory):
        if not self.macro_mode:
            return True
        if not memory:
            return True
        return memory.get("remaining", 0) <= 0

    def allowed(self, partial, memory, candidates):
        if self.macro_mode and memory and memory.get("remaining", 0) <= 0:
            return []
        allowed = self._allowed_simple(partial, candidates)

        if not self.macro_mode:
            return allowed

        # En modo macro, preferimos prolongar la misma intención: mover hacia vacías
        # mientras queden pasos en la memoria.
        if memory is None:
            memory = {}
        if allowed:
            memory["remaining"] = max(0, int(memory.get("remaining", 0)) - 1)
        return allowed


